select public.prepify_load_bank('Maths', 10, $j$[["The instrument used to draw circles and arcs is a:",["protractor","compass","set square","ruler"],"B",1,0,"f1e31c37ece1"],["The instrument used to measure an angle is a:",["compass","divider","protractor","ruler"],"C",1,0,"8f0bdd1f9497"],["The point where the perpendicular bisectors of the sides of a triangle meet is the:",["incentre","circumcentre","centroid","orthocentre"],"B",3,0,"94073aa96dd9"],["The point where the angle bisectors of a triangle meet is the:",["incentre","circumcentre","centroid","orthocentre"],"A",3,0,"a6803d4fa2bf"],["The point where the medians of a triangle meet is the:",["incentre","circumcentre","centroid","orthocentre"],"C",3,0,"fe6b2d2e17b6"],["The point where the altitudes of a triangle meet is the:",["incentre","circumcentre","centroid","orthocentre"],"D",3,0,"442c19d10d61"],["The centroid divides each median in the ratio:",["1 : 1","2 : 1","3 : 1","3 : 2"],"B",5,0,"0da175d57ffa"],["For an obtuse-angled triangle, the orthocentre lies:",["inside the triangle","on a side","outside the triangle","at a vertex"],"C",5,0,"e288e12db165"],["Which set of lengths can form a triangle?",["3 cm, 4 cm, 5 cm","2 cm, 3 cm, 6 cm","1 cm, 2 cm, 3 cm","4 cm, 4 cm, 9 cm"],"A",3,0,"396064b32d2f"],["Which set of lengths cannot form a triangle?",["5 cm, 6 cm, 7 cm","2 cm, 3 cm, 6 cm","3 cm, 3 cm, 3 cm","6 cm, 8 cm, 10 cm"],"B",3,0,"ddd22f137f3e"],["Two sides of a triangle are 7 cm and 3 cm. A possible length of the third side is:",["3 cm","4 cm","5 cm","10 cm"],"C",5,0,"ca26cc3a6cfe"],["Bisecting an angle of 60° gives two angles of:",["20°","30°","45°","60°"],"B",1,0,"4d7665ed83f5"],["Bisecting a right angle gives two angles of:",["30°","45°","60°","90°"],"B",1,0,"7829a2aef5ff"],["An angle of 120° can be constructed with a compass by:",["stepping off two 60° angles","bisecting a 60° angle","bisecting a 90° angle","adding 45° and 45°"],"A",3,0,"af026b545e04"],["The circle that passes through all three vertices of a triangle is its:",["incircle","circumcircle","tangent circle","concentric circle"],"B",3,0,"f9a42734078b"],["The circle that touches all three sides of a triangle from inside is its:",["incircle","circumcircle","semicircle","arc"],"A",3,0,"c43d395f5e15"],["A tangent to a circle is perpendicular to the:",["chord","radius at the point of contact","diameter parallel to it","arc"],"B",3,0,"ead67cfb078c"],["From a point outside a circle, the number of tangents that can be drawn is:",["1","2","3","infinitely many"],"B",3,0,"404b49a7855d"],["To construct a triangle when all three sides are given, we use the:",["SSS construction","SAS construction","ASA construction","RHS construction"],"A",1,0,"3fa5e5a876f8"],["Three villages are to share one water tank placed at the same distance from each village. The tank should be at the triangle's:",["incentre","circumcentre","centroid","orthocentre"],"B",3,1,"ee05a035242d"],["A fountain is to be placed in a triangular park so that it is equally far from all three boundary walls. It should be at the:",["incentre","circumcentre","centroid","orthocentre"],"A",3,1,"71286f779b0a"],["Every point on the perpendicular bisector of a line segment is:",["equidistant from both endpoints","on the segment","closer to one endpoint","equal to the segment's length away"],"A",3,0,"cc716168a782"],["Every point on the bisector of an angle is:",["equidistant from both arms of the angle","on one arm","at the vertex","equidistant from the vertex only"],"A",3,0,"0dd7297fdbc8"],["In a right-angled triangle, the circumcentre lies:",["at the right-angled vertex","at the midpoint of the hypotenuse","outside the triangle","at the centroid"],"B",5,0,"aec6092c141c"],["The hypotenuse of a right-angled triangle is 10 cm. The radius of its circumcircle is:",["5 cm","10 cm","20 cm","2.5 cm"],"A",5,0,"313a397d7c59"],["In an equilateral triangle, the incentre, circumcentre, centroid and orthocentre:",["all coincide","form a straight line only","are all outside the triangle","are at the vertices"],"A",3,0,"06e349f6b968"],["A student tries to construct a triangle with angles 90°, 60° and 40°. This is:",["possible, giving a right triangle","impossible, because the angles add to 190°","possible, giving an isosceles triangle","possible only with a compass"],"B",3,1,"802c8f733067"],["A metal triangle cut from a sheet balances on a pencil tip at one point. That point is the:",["centroid","incentre","circumcentre","orthocentre"],"A",3,1,"7a17ecdda840"],["Through three points that are not on one line, the number of circles that can be drawn is:",["none","exactly one","two","infinitely many"],"B",3,0,"7e63c6994c88"],["To construct the incircle of a triangle, you must first draw:",["two angle bisectors","two perpendicular bisectors","two medians","two altitudes"],"A",3,0,"672d3b320a23"],["A median of a triangle joins a vertex to the:",["midpoint of the opposite side","foot of the perpendicular","incentre","opposite vertex"],"A",1,0,"d7748a797852"],["Which set of lengths can form a triangle?",["6 cm, 4 cm, 10 cm","4 cm, 5 cm, 12 cm","9 cm, 3 cm, 9 cm","7 cm, 2 cm, 4 cm"],"C",3,0,"396064b32d2f"],["Which set of lengths can form a triangle?",["8 cm, 3 cm, 2 cm","6 cm, 4 cm, 8 cm","4 cm, 3 cm, 9 cm","6 cm, 3 cm, 11 cm"],"B",3,0,"396064b32d2f"],["Which set of lengths can form a triangle?",["3 cm, 9 cm, 11 cm","6 cm, 15 cm, 6 cm","6 cm, 8 cm, 2 cm","13 cm, 6 cm, 4 cm"],"A",3,0,"396064b32d2f"],["Which set of lengths can form a triangle?",["4 cm, 2 cm, 6 cm","11 cm, 7 cm, 6 cm","4 cm, 8 cm, 4 cm","3 cm, 6 cm, 9 cm"],"B",3,0,"396064b32d2f"],["Which set of lengths can form a triangle?",["3 cm, 6 cm, 12 cm","6 cm, 3 cm, 10 cm","11 cm, 3 cm, 5 cm","6 cm, 4 cm, 3 cm"],"D",3,0,"396064b32d2f"],["Which set of lengths can form a triangle?",["6 cm, 4 cm, 13 cm","3 cm, 2 cm, 7 cm","6 cm, 6 cm, 6 cm","6 cm, 11 cm, 4 cm"],"C",3,0,"396064b32d2f"],["Two sides of a triangle are 11 cm and 7 cm. Which of these could be the third side?",["4 cm","14 cm","21 cm","18 cm"],"B",5,0,"gen-maths-m10-third-side"],["Two sides of a triangle are 7 cm and 6 cm. Which of these could be the third side?",["8 cm","1 cm","13 cm","16 cm"],"A",5,0,"gen-maths-m10-third-side"],["Two sides of a triangle are 6 cm and 4 cm. Which of these could be the third side?",["2 cm","10 cm","11 cm","8 cm"],"D",5,0,"gen-maths-m10-third-side"],["Two sides of a triangle are 5 cm and 2 cm. Which of these could be the third side?",["7 cm","3 cm","6 cm","9 cm"],"C",5,0,"gen-maths-m10-third-side"],["Two sides of a triangle are 10 cm and 6 cm. Which of these could be the third side?",["4 cm","14 cm","16 cm","17 cm"],"B",5,0,"gen-maths-m10-third-side"],["Two sides of a triangle are 10 cm and 2 cm. Which of these could be the third side?",["13 cm","9 cm","8 cm","12 cm"],"B",5,0,"gen-maths-m10-third-side"],["A right-angled triangle has sides 5 cm, 12 cm and 13 cm. The radius of its circumcircle is:",["13 cm","6 cm","2.5 cm","6.5 cm"],"D",3,0,"gen-maths-m10-circumradius"],["A right-angled triangle has sides 12 cm, 16 cm and 20 cm. The radius of its circumcircle is:",["6 cm","8 cm","10 cm","20 cm"],"C",3,0,"gen-maths-m10-circumradius"],["A right-angled triangle has sides 3 cm, 4 cm and 5 cm. The radius of its circumcircle is:",["2 cm","2.5 cm","1.5 cm","5 cm"],"B",3,0,"gen-maths-m10-circumradius"],["A right-angled triangle has sides 6 cm, 8 cm and 10 cm. The radius of its circumcircle is:",["4 cm","3 cm","5 cm","10 cm"],"C",3,0,"gen-maths-m10-circumradius"],["A right-angled triangle has sides 8 cm, 15 cm and 17 cm. The radius of its circumcircle is:",["8.5 cm","4 cm","7.5 cm","17 cm"],"A",3,0,"gen-maths-m10-circumradius"],["A right-angled triangle has sides 9 cm, 12 cm and 15 cm. The radius of its circumcircle is:",["7.5 cm","6 cm","15 cm","4.5 cm"],"A",3,0,"gen-maths-m10-circumradius"],["A median of a triangle is 6 cm long. The distance from the vertex to the centroid along this median is:",["6 cm","2 cm","3 cm","4 cm"],"D",3,0,"gen-maths-m10-centroid"],["A median of a triangle is 15 cm long. The distance from the vertex to the centroid along this median is:",["15 cm","7.5 cm","10 cm","5 cm"],"C",3,0,"gen-maths-m10-centroid"],["A median of a triangle is 21 cm long. The distance from the vertex to the centroid along this median is:",["14 cm","7 cm","21 cm","10.5 cm"],"A",3,0,"gen-maths-m10-centroid"],["A median of a triangle is 24 cm long. The distance from the vertex to the centroid along this median is:",["8 cm","16 cm","12 cm","24 cm"],"B",3,0,"gen-maths-m10-centroid"],["A median of a triangle is 27 cm long. The distance from the vertex to the centroid along this median is:",["9 cm","18 cm","27 cm","13.5 cm"],"B",3,0,"gen-maths-m10-centroid"],["A median of a triangle is 18 cm long. The distance from the vertex to the centroid along this median is:",["9 cm","12 cm","6 cm","18 cm"],"B",3,0,"gen-maths-m10-centroid"]]$j$::jsonb, true);
select public.prepify_load_bank('Maths', 11, $j$[["The mean of 2, 4, 6, 8 and 10 is:",["5","6","7","30"],"B",1,0,"63ed5aba7a04"],["The median of 3, 7, 1, 9 and 5 is:",["1","5","7","9"],"B",3,0,"a0c7aa35c6e4"],["The median of 2, 4, 6 and 8 is:",["4","5","6","10"],"B",3,0,"9c3a4cfedcde"],["The mode of 2, 3, 3, 5, 7, 3, 5 is:",["2","3","5","7"],"B",1,0,"c8520d3b99b1"],["The range of 12, 5, 20 and 8 is:",["8","12","15","20"],"C",1,0,"3deb802b7a11"],["The mean of 10, 20, 30 and 40 is:",["20","25","30","100"],"B",1,0,"0cae29c707cf"],["The class mark (mid-point) of the class 10–20 is:",["10","15","20","30"],"B",3,0,"3ffd04d915d3"],["The class width of the classes 0–10, 10–20, 20–30 is:",["5","10","20","30"],"B",1,0,"e88c19c7d65b"],["In a pie chart, a category with 10 out of 40 students gets a sector angle of:",["10°","40°","90°","120°"],"C",3,0,"08495e7ffa71"],["Which average is most affected by a single very large value (an outlier)?",["Mean","Median","Mode","All equally"],"A",3,0,"b9e34f93301a"],["The sum of the deviations of the values from their mean is always:",["0","1","the mean","the range"],"A",5,0,"49557043d1da"],["The mean of 5 numbers is 12. Their sum is:",["17","50","60","2.4"],"C",3,0,"bb5140e72d84"],["The mean of 4 numbers is 10. A fifth number, 20, is added. The new mean is:",["10","12","15","30"],"B",5,0,"253459781499"],["For the frequencies 3, 5 and 7, the cumulative frequencies are:",["3, 8, 15","3, 5, 7","7, 12, 15","3, 15, 8"],"A",3,0,"444062bd1d1f"],["Grouped continuous data such as heights of students is best shown by a:",["pie chart","histogram","pictograph","line of symmetry"],"B",3,0,"daa2978bfbfd"],["Favourite colours of a class are best shown by a:",["bar chart","histogram","frequency polygon only","scatter graph"],"A",1,0,"a31a4b8b2428"],["A data set that has two modes is called:",["unimodal","bimodal","skewed","grouped"],"B",3,0,"cbf6f2c221cb"],["For x = 1, 2, 3 with frequencies 2, 3, 5, the mean Σfx ÷ Σf is:",["2","2.3","2.5","3"],"B",5,0,"f76b22ee1821"],["A shoe shop wants to know which shoe size to stock the most. The average it should use is the:",["mean","median","mode","range"],"C",3,1,"9d4d478a1e7b"],["The range of a data set measures its:",["spread","centre","most common value","total"],"A",3,0,"670c5bafe338"],["The median of 7, 2, 9, 4, 5 and 8 is:",["5","6","6.5","7"],"B",5,0,"41db949761af"],["The midday temperatures over five days were 30°C, 32°C, 31°C, 35°C and 32°C. The mean temperature was:",["31°C","32°C","33°C","35°C"],"B",3,1,"254932119177"],["The angles of all the sectors in a pie chart add up to:",["100°","180°","270°","360°"],"D",1,0,"f5ba6eade8a0"],["The data 1, 2, 2, 3, 3, 4 has mode(s):",["2 only","3 only","2 and 3","4"],"C",3,0,"3381a32d916d"],["If 5 is added to every value in a data set, the mean:",["stays the same","increases by 5","doubles","decreases by 5"],"B",5,0,"fbd0237b6f9d"],["Data collected by the investigator directly for their own purpose is called:",["primary data","secondary data","grouped data","cumulative data"],"A",3,0,"cff83f3c0f09"],["Data taken from newspapers, books or websites is called:",["primary data","secondary data","raw frequency","class mark"],"B",3,0,"ce7f8e988772"],["A cricketer scored 20, 45, 0, 80 and 55 runs in five innings. The average score per innings is:",["40","45","50","200"],"A",3,1,"504dded9542b"],["The monthly salaries in an office are Rs 30,000 for nine staff and Rs 3,00,000 for the manager. Which average best describes a typical salary?",["Mean","Median","Maximum","Range"],"B",5,1,"325894e4fb34"],["A frequency polygon is drawn by joining the:",["mid-points of the tops of histogram bars","corners of the bars","class boundaries","cumulative totals"],"A",3,0,"e723d7197bb1"],["In a class of 30 students, 12 walk to school. In a pie chart the \"walk\" sector is:",["12°","120°","144°","180°"],"C",5,0,"1371ec134391"],["The mean of 22, 16, 10, 20, 5, 5 is:",["14","13","11","78"],"B",3,0,"gen-maths-m11-mean"],["The mean of 8, 21, 10, 29 is:",["18